// Get input data
const input = $input.item.json;

const o = Array.isArray(input.order) ? input.order[0] : null;
const n = Array.isArray(input.newitem) ? input.newitem[0] : null;

const confirmed = ["true", "yes"].includes(
  String(input.confirmed || "").trim().toLowerCase()
);

const risk = parseInt(input.risk_score, 10) || 0;
const refunds90 = parseInt(input.refunds_last_90d, 10) || 0;

// Prepare output
const res = (ok, msg, credit = 0.0) => ({
  allowed: ok ? "true" : "false",
  message: msg,
  credit: Number(credit).toFixed(2),
  currency: o ? String(o.currency || "") : "",
  new_item: n ? String(n.new_item || "") : "",
  new_price: n ? String(n.price ?? "") : "",
  old_item: o ? String(o.item || "") : "",
  old_sku: o ? String(o.sku || "") : "",
  old_size: o ? String(o.size || "") : "",
  policy_version: o ? String(o.policy_version || "") : ""
});

let result;

if (!confirmed) {
  result = res(false, "The customer has not confirmed yet.");
} else if (!o) {
  result = res(false, "Order not found for this customer");
} else if (
  risk >= (parseInt(o.risk_score_escalate, 10) || 0) ||
  refunds90 >= (parseInt(o.serial_refund_threshold, 10) || 0)
) {
  result = res(false, "This needs a person to review. Escalate instead.");
} else if (
  String(o.refunded || "").toLowerCase() === "yes" ||
  (parseInt(o.refund_count, 10) || 0) > 0
) {
  result = res(false, "This order was already refunded.");
} else if (
  (parseInt(o.return_count, 10) || 0) > 0 ||
  (parseInt(o.exchange_count, 10) || 0) > 0
) {
  result = res(
    false,
    "A return or exchange is already in progress for this order."
  );
} else if (String(o.order_status || "").toLowerCase() !== "delivered") {
  result = res(
    false,
    "The order has not been delivered yet, so it cannot be exchanged."
  );
} else if (
  (parseInt(o.return_window_days, 10) || 0) -
    (parseInt(o.days_since_delivery, 10) || 0) < 0
) {
  result = res(
    false,
    `Delivered ${o.days_since_delivery} days ago; the exchange window is ${o.return_window_days} days.`
  );
} else if (!n) {
  result = res(false, "That item and size is not in the catalogue.");
} else if ((parseInt(n.stock, 10) || 0) < 1) {
  result = res(false, "That item has just gone out of stock.");
} else if (
  (parseFloat(n.price) || 0) > (parseFloat(o.amount) || 0)
) {
  result = res(
    false,
    "The new item costs more than the order. A person must handle a price difference. Escalate instead."
  );
} else {
  const credit = Math.max(
    (parseFloat(o.amount) || 0) - (parseFloat(n.price) || 0),
    0
  );

  result = res(true, "OK", credit);
}

// Return output in n8n format
return {
  json: result
};

parameters.query:
SELECT
    (
        SELECT CONCAT(
            'R',
            LPAD(
                CAST(
                    COALESCE(
                        MAX(TRY_CAST(SUBSTRING(return_id, 2) AS INT)),
                        0
                    ) + 1 AS STRING
                ),
                4,
                '0'
            )
        )
        FROM workspace.agentic_support.returns
    ) AS return_id,
    (
        SELECT CONCAT(
            'X',
            LPAD(
                CAST(
                    COALESCE(
                        MAX(TRY_CAST(SUBSTRING(exchange_id, 2) AS INT)),
                        0
                    ) + 1 AS STRING
                ),
                4,
                '0'
            )
        )
        FROM workspace.agentic_support.exchanges
    ) AS exchange_id;

